import React, { useState, useEffect } from 'react';
import { useNavigate } from 'react-router-dom';
import api from '../services/api';
import './fichiersCSS/StudentNotes.css';

function StudentNotes() {
  const navigate = useNavigate();
  const [notes, setNotes] = useState([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState('');

  useEffect(() => {
    const token = localStorage.getItem('token');
    if (!token) {
      navigate('/login');
      return;
    }
    fetchNotes();
  }, [navigate]);

  const fetchNotes = async () => {
    try {
      setLoading(true);
      const response = await api.get('/api/student/grades');
      setNotes(response.data.grades || []);
    } catch (error) {
      console.error('Erreur chargement notes:', error);
      setError('Erreur lors du chargement des notes');
    } finally {
      setLoading(false);
    }
  };

  const handleBack = () => {
    navigate('/dashboard-student');
  };

  const getNoteColor = (note) => {
    if (note >= 16) return '#48bb78';
    if (note >= 12) return '#4299e1';
    if (note >= 10) return '#ed8936';
    return '#e53e3e';
  };

  const getNoteStatus = (note) => {
    if (note >= 10) return 'Admis';
    return 'Non admis';
  };

  const calculateStats = () => {
    if (notes.length === 0) return null;
    
    const total = notes.reduce((sum, note) => sum + parseFloat(note.note), 0);
    const moyenne = total / notes.length;
    const admis = notes.filter(note => note.note >= 10).length;
    const nonAdmis = notes.filter(note => note.note < 10).length;
    
    return {
      moyenne: moyenne.toFixed(2),
      admis,
      nonAdmis,
      total: notes.length
    };
  };

  const stats = calculateStats();

  if (loading) {
    return (
      <div className="loading-container">
        <div className="spinner"></div>
        <p>Chargement de vos notes...</p>
      </div>
    );
  }

  return (
    <div className="student-notes-container">
      <header className="student-notes-header">
        <button onClick={handleBack} className="back-button">
          ← Retour au Dashboard
        </button>
        <h1 className="title">Mes Notes</h1>
        <div className="header-actions">
          <span className="counter">
            {notes.length} note{notes.length > 1 ? 's' : ''}
          </span>
        </div>
      </header>

      <main className="student-notes-main">
        {error && (
          <div className="error-alert">
            {error}
          </div>
        )}

        {stats && (
          <div className="stats-grid">
            <div className="stat-card">
              <div className="stat-number">{stats.moyenne}</div>
              <div className="stat-label">Moyenne Générale</div>
            </div>
            <div className="stat-card">
              <div className="stat-number" style={{color: '#48bb78'}}>{stats.admis}</div>
              <div className="stat-label">Notes ≥ 10</div>
            </div>
            <div className="stat-card">
              <div className="stat-number" style={{color: '#e53e3e'}}>{stats.nonAdmis}</div>
              <div className="stat-label">Notes </div>
            </div>
            <div className="stat-card">
              <div className="stat-number">{stats.total}</div>
              <div className="stat-label">Total des notes</div>
            </div>
          </div>
        )}

        {notes.length === 0 ? (
          <div className="empty-state">
            <div className="empty-icon">📊</div>
            <h3>Aucune note disponible</h3>
            <p>Vos notes apparaîtront ici une fois publiées par vos professeurs.</p>
          </div>
        ) : (
          <div className="notes-table">
            <table className="table">
              <thead>
                <tr>
                  <th className="th">Cours</th>
                  <th className="th">Niveau</th>
                  <th className="th">Note</th>
                  <th className="th">Statut</th>
                  <th className="th">Professeur</th>
                  <th className="th">Date</th>
                </tr>
              </thead>
              <tbody>
                {notes.map((note) => (
                  <tr key={note.id} className="tr">
                    <td className="td">
                      <strong>{note.course_title}</strong>
                    </td>
                    <td className="td">
                      <span className="level-badge">{note.course_level}</span>
                    </td>
                    <td className="td">
                      <span 
                        className="note-badge"
                        style={{ background: getNoteColor(note.note) }}
                      >
                        {note.note}/20
                      </span>
                    </td>
                    <td className="td">
                      <span 
                        className="status-badge"
                        style={{
                          background: note.note >= 10 ? '#c6f6d5' : '#fed7d7',
                          color: note.note >= 10 ? '#22543d' : '#742a2a'
                        }}
                      >
                        {getNoteStatus(note.note)}
                      </span>
                    </td>
                    <td className="td">{note.professeur_nom}</td>
                    <td className="td">
                      {new Date(note.date_evaluation).toLocaleDateString('fr-FR')}
                    </td>
                  </tr>
                ))}
              </tbody>
            </table>
          </div>
        )}
      </main>
    </div>
  );
}

export default StudentNotes;
